<script setup lang="ts">
import type {ShoppingTactics} from '../decision/shopping-tactics';
import {dataset} from '../game/tft-data';
import {combatFormName,combatAuxiliaryName} from '../game/combat-unit-identity';
defineProps<{advice?:ShoppingTactics}>();
const name=(id:string)=>dataset.characterById(id)?.display_name??'待更新';
const percent=(n:number)=>Math.round(n*100)+'%';
const unitTitle=(id:string,star:number,combatId?:string)=>[name(id),combatId?combatFormName(combatId):null,star+'星'].filter(Boolean).join(' · ');
</script>
<template><section class="shopping-tactics" data-shopping-tactics :data-ready="advice?.ready??false">
  <header><h2>当前换牌</h2><small v-if="advice?.ready" :title="`比较 ${advice.searchedPlans} 套合法购买组合、${advice.searchedBoards} 个场上棋盘；基础最多两牌联动${advice.deploymentSearch?'，另比较MetaTFT观测重组（最多换下'+advice.maxSwaps+'个实体，限量候选）':''}；保留原装备，不含站位或接装。`">{{ advice.deploymentSearch?.observedBoards?'含观测重组':advice.provisional?'常规规则参考':'本地模型' }}</small></header>
  <div v-if="advice?.ready" class="tactical-grid">
    <article v-for="choice in advice.choices" :key="choice.id" :data-tactical-choice="choice.id">
      <header><strong>{{ choice.id==='mainline'||choice.buy.length?choice.title:choice.incoming?.length||choice.outgoing?.length?'免费换牌':'保持当前' }}</strong><span>余 <b>{{ choice.goldAfter }}</b> 金</span></header>
      <div v-if="choice.buy.length" class="tactical-purchases"><span v-for="buy in choice.buy" :key="buy.id" :title="name(buy.id)+' · 商店第 '+buy.slots.map(s=>s+1).join('、')+' 格'"><img :src="dataset.characterById(buy.id)?.image_path" :alt="name(buy.id)"/><b>×{{ buy.quantity }}</b></span></div>
      <div v-if="choice.incoming?.length||choice.outgoing?.length" class="tactical-changes"><div v-for="group in [{label:'换上',units:choice.incoming},{label:'换下',units:choice.outgoing}]" :key="group.label" class="tactical-diff"><small>{{ group.label }}</small><span v-if="!group.units?.length">—</span><span v-for="unit in group.units" :key="unit.key" :title="unitTitle(unit.id,unit.star,unit.combatId)+(unit.items.length?' · '+unit.items.map(id=>dataset.item(id)?.display_name??'装备待更新').join('、'):'')"><img :src="dataset.characterById(unit.id)?.image_path" :alt="name(unit.id)"/><small>{{ '★'.repeat(unit.star) }}</small></span></div></div>
      <footer><span :title="'同一对手分布下的单场模型估计；主线方案优先容纳已选双核，可能暂时降低战力。'+advice.gaps.join(' · ')">{{ advice.weightSource==='uniform'?'全场':'下场' }} <b>{{ choice.winRate===null?'待补齐':percent(choice.winRate) }}{{ advice.gaps.length?'*':'' }}</b><i v-if="choice.delta!==null" :class="{negative:choice.delta<0}">{{ choice.delta>=0?'+':'' }}{{ (choice.delta*100).toFixed(1) }}pt</i></span><small :title="'利息分支：落败 '+choice.interestIfLose+'，获胜 '+choice.interestIfWin">息 {{ choice.interestIfLose }}{{ choice.interestIfWin!==choice.interestIfLose?'–'+choice.interestIfWin:'' }}</small></footer>
      <details data-tactical-details><summary>换牌明细</summary><p v-if="choice.observedSources?.length" class="tactical-source">MetaTFT 观测引导 · 仅使用已持 / 本次购买的牌</p><div v-for="upgrade in choice.upgraded" :key="upgrade.id" class="tactical-upgrade">{{ name(upgrade.id) }} {{ upgrade.before }} → {{ upgrade.after }} 星</div><div class="tactical-lineup"><span v-for="(id,i) in choice.onBoard" :key="id+i" :title="unitTitle(id,choice.onBoardStars[i],choice.onBoardCombatIds[i])"><img :src="dataset.characterById(id)?.image_path" :alt="name(id)"/><small>{{ '★'.repeat(choice.onBoardStars[i]) }}</small><span v-if="choice.onBoardItems?.[i]?.length" class="tactical-items"><img v-for="(item,j) in choice.onBoardItems[i]" :key="j" :src="dataset.item(item)?.image_path" :alt="dataset.item(item)?.display_name??'装备待更新'" :title="dataset.item(item)?.display_name??'装备待更新'"/></span></span></div></details>
      <div v-if="choice.auxiliary.length" class="tactical-auxiliary"><span v-for="(unit,index) in choice.auxiliary" :key="index" :title="combatAuxiliaryName(unit.id)+' · '+unit.star+'星 · '+unit.items.map(id=>dataset.item(id)?.display_name??'装备待更新').join('、')">保留 · {{ combatAuxiliaryName(unit.id) }}<img v-for="(item,j) in unit.items" :key="j" :src="dataset.item(item)?.image_path" :alt="dataset.item(item)?.display_name??'装备待更新'"/></span></div>
    </article>
  </div>
  <p v-else>{{ advice?.reason??'等待金币与场上棋盘' }}</p>
</section></template>
<style scoped>
.tactical-changes{margin:14px 0 17px}.tactical-changes .tactical-diff{margin-top:9px}.tactical-source{font-size:10px;line-height:1.7;color:var(--muted);margin:12px 0}

.tactical-lineup>span{display:flex;flex-direction:column;align-items:center;gap:3px}.tactical-lineup>span>small{font-size:7px;color:#bba66d;line-height:1}
.tactical-auxiliary{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px;color:#82938d;font-size:10px}.tactical-auxiliary>span{display:flex;align-items:center;gap:4px}.tactical-auxiliary img{width:13px;height:13px;border:1px solid #53615e;border-radius:2px}
.tactical-grid footer i.negative{color:#c58f7f}.tactical-diff{display:flex;align-items:center;gap:7px;margin-top:10px}.tactical-diff>small{font-size:10px;color:var(--muted);min-width:25px}.tactical-diff>span{display:flex;flex-direction:column;align-items:center;gap:3px;color:#66665e}.tactical-diff img{width:25px;height:25px;object-fit:cover;border:1px solid #66665e;border-radius:3px}.tactical-diff span small{font-size:7px;color:#bba66d}.tactical-upgrade{font-size:10px;color:#b7ad89;margin-top:10px}.tactical-items{display:flex;gap:1px}.tactical-lineup .tactical-items img{width:10px;height:10px;border-radius:1px}
.shopping-tactics{margin:0 0 28px;padding:18px 20px;background:var(--surface);border:1px solid #343431;border-radius:8px}.shopping-tactics>header,.tactical-grid article>header,.tactical-grid footer{display:flex;justify-content:space-between;align-items:center}.shopping-tactics h2{font-size:14px;font-weight:500;color:#cbd1cb;margin:0}.shopping-tactics>header>small{font-size:10px;color:var(--faint)}.tactical-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:16px}.tactical-grid article{background:var(--surface);border:1px solid #343431;border-radius:5px;padding:13px}.tactical-grid article strong{font-size:12px;font-weight:500;color:#b7c4b6}.tactical-grid article header>span{font-size:11px;color:var(--faint)}.tactical-grid article header b{color:#cfbea0;font-weight:500}.tactical-purchases{display:flex;align-items:center;gap:8px;min-height:45px;margin:12px 0}.tactical-purchases>span{position:relative;display:block;width:32px;height:32px}.tactical-purchases img{width:100%;height:100%;object-fit:cover;border-radius:3px;border:1px solid #8e8b68}.tactical-purchases b{position:absolute;bottom:-4px;right:-6px;font-size:10px;line-height:13px;background:#b1a37b;color:var(--surface);padding:0 3px;border-radius:2px}.tactical-purchases>small{font-size:11px;color:var(--faint)}.tactical-grid footer{font-size:11px;color:var(--muted)}.tactical-grid footer b{font-size:13px;font-weight:500;color:#bbccb6;margin-left:5px}.tactical-grid footer i{font-size:10px;font-style:normal;color:#8ea792;margin-left:8px}.tactical-grid footer small{font-size:10px;color:#a39274}.tactical-grid details{font-size:10px;color:var(--faint);margin-top:12px}.tactical-grid summary{cursor:pointer}.tactical-lineup{display:flex;gap:5px;margin-top:10px;flex-wrap:wrap}.tactical-lineup img{width:25px;height:25px;object-fit:cover;border:1px solid #66665e;border-radius:3px}.shopping-tactics>p{font-size:11px;color:var(--faint);margin:12px 0 0}
</style>
